def min_coins_to_color(n, m, grid):
    # Initialize the cost matrix
    cost = [[0] * m for _ in range(n)]

    # Fill the cost matrix based on the grid
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                cost[i][j] = 1

    # Calculate the minimum coins needed
    total_cost = 0

    # Process the last column
    for i in range(n):
        if cost[i][m-1] == 1:
            total_cost += 4
            for k in range(i+1, n):
                cost[k][m-1] ^= 1

    # Process the last row
    for j in range(m-1):
        if cost[n-1][j] == 1:
            total_cost += 2
            for k in range(j+1, m):
                cost[n-1][k] ^= 1

    # Process the top-left corner
    if cost[0][0] == 1:
        total_cost += 1
        for i in range(1, n):
            cost[i][0] ^= 1
        for j in range(1, m):
            cost[0][j] ^= 1

    return total_cost

